import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtils_escapeJava_TriageGen5Test {







    @Test
    public void testEscapeJava_SpecialCharacters() {
        // Test backslash, quotes, and common control characters
        assertEquals("Backslash: \\\\", StringEscapeUtils.escapeJava("Backslash: \\"));
        assertEquals("Double Quote: \\\"", StringEscapeUtils.escapeJava("Double Quote: \""));
        assertEquals("Single Quote: \\'", StringEscapeUtils.escapeJava("Single Quote: '"));
    }








}

package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
