import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtils_escapeJava_TriageGen5Test {













    @Test
    public void testEscapeJava_MixedContent() {
        String input = "Line 1\nLine 2\t\"Quoted\" \\ Backslash";
        String expected = "Line 1\\nLine 2\\t\\\"Quoted\\\" \\\\ Backslash";
        assertEquals(expected, StringEscapeUtils.escapeJava(input));
    }


}

package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
