import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringEscapeUtils_escapeJava_TriageGen5Test {















    @Test
    public void testEscapeJava_RoundTrip() {
        // Verifies that unescape(escape(x)) == x for standard cases
        String input = "Complex String: \n\t\"'\\ \u001b";
        String escaped = StringEscapeUtils.escapeJava(input);
        assertEquals(input, StringEscapeUtils.unescapeJava(escaped));
    }
}
